package httpapi

import (
	"sync"
	"time"
)

type aiRequestState struct {
	windowStart time.Time
	requests    int
	active      int
}

type aiRequestLimiter struct {
	mu            sync.Mutex
	users         map[string]aiRequestState
	maxPerMinute  int
	maxConcurrent int
	now           func() time.Time
}

func newAIRequestLimiter() *aiRequestLimiter {
	return &aiRequestLimiter{users: make(map[string]aiRequestState), maxPerMinute: 30,
		maxConcurrent: 2, now: time.Now}
}

func (l *aiRequestLimiter) acquire(userID string) (bool, string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
	state := l.users[userID]
	if state.windowStart.IsZero() || now.Sub(state.windowStart) >= time.Minute {
		state.windowStart = now
		state.requests = 0
	}
	if state.active >= l.maxConcurrent {
		return false, "동시에 실행할 수 있는 AI 요청 수를 초과했습니다"
	}
	if state.requests >= l.maxPerMinute {
		return false, "분당 AI 요청 한도를 초과했습니다"
	}
	state.active++
	state.requests++
	l.users[userID] = state
	if len(l.users) > 4096 {
		for id, candidate := range l.users {
			if candidate.active == 0 && now.Sub(candidate.windowStart) > 2*time.Minute {
				delete(l.users, id)
			}
		}
	}
	return true, ""
}

func (l *aiRequestLimiter) release(userID string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	state, ok := l.users[userID]
	if !ok {
		return
	}
	if state.active > 0 {
		state.active--
	}
	l.users[userID] = state
}
package httpapi

import (
	"fmt"
	"net/http"
	"sort"
	"strings"
	"sync"
	"time"
)

const (
	loginFailureLimit    = 5
	loginFailureWindow   = 5 * time.Minute
	loginFailureCapacity = 10_000
)

type loginFailureEntry struct {
	count     int
	expiresAt time.Time
}

type loginRateLimiter struct {
	mu       sync.Mutex
	failures map[string]loginFailureEntry
	now      func() time.Time
	limit    int
	window   time.Duration
	capacity int
}

func newLoginRateLimiter() *loginRateLimiter {
	return &loginRateLimiter{
		failures: make(map[string]loginFailureEntry),
		now:      time.Now,
		limit:    loginFailureLimit,
		window:   loginFailureWindow,
		capacity: loginFailureCapacity,
	}
}

func (l *loginRateLimiter) blocked(key string) (bool, time.Duration) {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
	entry, ok := l.failures[key]
	if !ok {
		return false, 0
	}
	if !entry.expiresAt.After(now) {
		delete(l.failures, key)
		return false, 0
	}
	if entry.count < l.limit {
		return false, 0
	}
	return true, entry.expiresAt.Sub(now)
}

func (l *loginRateLimiter) failed(key string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
	entry := l.failures[key]
	if !entry.expiresAt.After(now) {
		entry = loginFailureEntry{expiresAt: now.Add(l.window)}
	}
	entry.count++
	l.failures[key] = entry
	if len(l.failures) > l.capacity {
		l.evict(key, now)
	}
}

// evict brings the table back under capacity without giving up a lockout it
// does not have to. Expired entries go first, then keys that have not reached
// the limit yet; only when the table holds nothing but live lockouts do those
// go, earliest expiry first. Picking victims by map order would let a client
// that locked one account flood failures against other usernames until the
// lockout it wanted gone was evicted. The key that just failed always stays.
func (l *loginRateLimiter) evict(keep string, now time.Time) {
	for existingKey, existing := range l.failures {
		if !existing.expiresAt.After(now) {
			delete(l.failures, existingKey)
		}
	}
	for existingKey, existing := range l.failures {
		if len(l.failures) <= l.capacity {
			return
		}
		if existingKey != keep && existing.count < l.limit {
			delete(l.failures, existingKey)
		}
	}
	if len(l.failures) <= l.capacity {
		return
	}
	locked := make([]string, 0, len(l.failures))
	for existingKey := range l.failures {
		if existingKey != keep {
			locked = append(locked, existingKey)
		}
	}
	sort.Slice(locked, func(i, j int) bool {
		return l.failures[locked[i]].expiresAt.Before(l.failures[locked[j]].expiresAt)
	})
	for _, existingKey := range locked {
		if len(l.failures) <= l.capacity {
			return
		}
		delete(l.failures, existingKey)
	}
}

func (l *loginRateLimiter) succeeded(key string) {
	l.mu.Lock()
	delete(l.failures, key)
	l.mu.Unlock()
}

func loginRateKey(r *http.Request, username string) string {
	return remoteIP(r) + "\x00" + strings.ToLower(strings.TrimSpace(username))
}

func (s *Server) rejectRateLimitedLogin(w http.ResponseWriter, r *http.Request, key string, openBao bool) bool {
	if s.loginLimiter == nil {
		return false
	}
	blocked, retryAfter := s.loginLimiter.blocked(key)
	if !blocked {
		return false
	}
	seconds := int((retryAfter + time.Second - 1) / time.Second)
	if seconds < 1 {
		seconds = 1
	}
	w.Header().Set("Retry-After", fmt.Sprintf("%d", seconds))
	if openBao {
		baoError(w, http.StatusTooManyRequests, "too many login attempts; retry later")
	} else {
		writeError(w, r, http.StatusTooManyRequests, "login_rate_limited", "로그인 시도가 너무 많습니다. 잠시 후 다시 시도하세요")
	}
	return true
}
package tracking

import (
	"net/url"
	"sort"
	"strings"
	"sync"
	"time"
)

// MaxViolations bounds the recorder. A blocked request repeats on every page
// view, so what matters is which origins are blocked, not how many times — a
// small ring of distinct origins is enough to fix a snippet.
const MaxViolations = 100

// Violation is one origin the content security policy refused, kept with the
// directive that refused it so the console can say what to allow.
type Violation struct {
	Origin    string    `json:"origin"`
	Directive string    `json:"directive"`
	Page      string    `json:"page"`
	Count     int       `json:"count"`
	FirstSeen time.Time `json:"first_seen"`
	LastSeen  time.Time `json:"last_seen"`
	Allowed   bool      `json:"allowed"`
}

// Recorder collects the policy violations browsers report. It is deliberately
// in memory: the reports are a live troubleshooting aid for the person pasting
// a snippet, not an audit record, and an unauthenticated endpoint must not be
// able to grow the database.
type Recorder struct {
	mutex      sync.Mutex
	violations map[string]*Violation
	now        func() time.Time
}

func NewRecorder() *Recorder {
	return &Recorder{violations: make(map[string]*Violation), now: time.Now}
}

// Record notes one blocked request. Anything that is not an http origin, such
// as a browser extension or a data: URL, is ignored because allowing it is
// neither possible nor useful.
func (r *Recorder) Record(blockedURI, directive, page string) {
	origin := originOf(blockedURI)
	if origin == "" {
		return
	}
	directive = strings.TrimSpace(strings.ToLower(directive))
	if index := strings.IndexByte(directive, ' '); index > 0 {
		directive = directive[:index]
	}
	if directive == "" {
		directive = "connect-src"
	}
	page = strings.TrimSpace(page)
	if len(page) > 512 {
		page = page[:512]
	}
	r.mutex.Lock()
	defer r.mutex.Unlock()
	key := directive + " " + origin
	if existing, found := r.violations[key]; found {
		existing.Count++
		existing.LastSeen = r.now()
		existing.Page = page
		return
	}
	if len(r.violations) >= MaxViolations {
		r.evictOldest()
	}
	moment := r.now()
	r.violations[key] = &Violation{Origin: origin, Directive: directive, Page: page, Count: 1, FirstSeen: moment, LastSeen: moment}
}

func (r *Recorder) evictOldest() {
	var oldestKey string
	var oldest time.Time
	for key, violation := range r.violations {
		if oldestKey == "" || violation.LastSeen.Before(oldest) {
			oldestKey, oldest = key, violation.LastSeen
		}
	}
	delete(r.violations, oldestKey)
}

// List returns the blocked origins, most recent first, marking the ones the
// current configuration already allows so a fixed snippet stops nagging.
func (r *Recorder) List(config Config) []Violation {
	allowed := make(map[string]struct{})
	scripts, connects, images := config.PolicySources()
	for _, group := range [][]string{scripts, connects, images} {
		for _, origin := range group {
			allowed[strings.ToLower(strings.TrimSuffix(origin, "/"))] = struct{}{}
		}
	}
	r.mutex.Lock()
	defer r.mutex.Unlock()
	items := make([]Violation, 0, len(r.violations))
	for _, violation := range r.violations {
		copied := *violation
		_, known := allowed[copied.Origin]
		copied.Allowed = known || matchesWildcard(copied.Origin, allowed)
		items = append(items, copied)
	}
	sort.Slice(items, func(first, second int) bool {
		if items[first].LastSeen.Equal(items[second].LastSeen) {
			return items[first].Origin < items[second].Origin
		}
		return items[first].LastSeen.After(items[second].LastSeen)
	})
	return items
}

// Forget drops the recorded violations, which is what an administrator does
// after fixing a snippet to check whether anything is still blocked.
func (r *Recorder) Forget() {
	r.mutex.Lock()
	defer r.mutex.Unlock()
	r.violations = make(map[string]*Violation)
}

// matchesWildcard covers policy entries such as https://*.google-analytics.com.
func matchesWildcard(origin string, allowed map[string]struct{}) bool {
	parsed, err := url.Parse(origin)
	if err != nil || parsed.Host == "" {
		return false
	}
	for pattern := range allowed {
		star := strings.Index(pattern, "*.")
		if star < 0 {
			continue
		}
		if strings.HasPrefix(origin, pattern[:star]) && strings.HasSuffix(parsed.Host, pattern[star+1:]) {
			return true
		}
	}
	return false
}

// AddAllowedHost appends an origin to the allow list, leaving the existing
// entries and their order alone. It returns "" when the origin is not an
// http(s) address, because such a thing cannot be allowed.
func AddAllowedHost(existing, origin string) (string, bool) {
	origin = originOf(origin)
	if origin == "" {
		return existing, false
	}
	for _, host := range SplitHosts(existing) {
		if strings.EqualFold(strings.TrimSuffix(host, "/"), origin) {
			return existing, true
		}
	}
	if strings.TrimSpace(existing) == "" {
		return origin, true
	}
	return strings.TrimSpace(existing) + ", " + origin, true
}
