const jsonLdMatches = [...index.matchAll(/<script\s+type="application\/ld\+json">([\s\S]*?)<\/script>/g)];
if (jsonLdMatches.length === 0) {
  failures.push('JSON-LD 블록이 없습니다.');
} else {
